create table if not exists channels(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id) on delete cascade,user_id uuid not null references users(id) on delete cascade,youtube_channel_id text unique,youtube_handle text,name text,description text,profile_image text,banner text,subscribers bigint default 0,total_views bigint default 0,video_count int default 0,country text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists channel_credentials(id uuid primary key default gen_random_uuid(),channel_id uuid not null unique references channels(id) on delete cascade,access_token text,refresh_token text,expires_at timestamptz,scope text,updated_at timestamptz not null default now());
